<template>
  <div class="routes-page">
    <v-snackbar v-model="snackbar" location="right top" :timeout="sb_timeout" :color="sb_type" elevation="10" class="busgo-snackbar">
      <div class="snackbar-content"><v-icon :icon="sb_icon" size="22" /><div><div class="snackbar-title">{{ sb_title }}</div><div class="snackbar-message">{{ sb_message }}</div></div></div>
    </v-snackbar>

    <header class="page-header">
      <div class="page-heading"><div class="page-icon"><v-icon size="21">mdi-map-marker-path</v-icon></div><div><h1 class="page-title">Rutas</h1><p class="page-subtitle">Administra recorridos, paradas y tramos comerciales</p></div></div>
      <v-btn class="add-button" prepend-icon="mdi-plus" elevation="0" @click="showAdd">Agregar ruta</v-btn>
    </header>

    <v-container fluid class="page-content">
      <v-row class="summary-row">
        <v-col cols="12" sm="4"><div class="summary-card"><div class="summary-icon summary-icon--blue"><v-icon size="19">mdi-routes</v-icon></div><div><div class="summary-value">{{ branchRoutes.length }}</div><div class="summary-label">Rutas registradas</div></div></div></v-col>
        <v-col cols="12" sm="4"><div class="summary-card"><div class="summary-icon summary-icon--green"><v-icon size="19">mdi-map-marker-check-outline</v-icon></div><div><div class="summary-value">{{ uniqueLocations }}</div><div class="summary-label">Ubicaciones conectadas</div></div></div></v-col>
        <v-col cols="12" sm="4"><div class="summary-card"><div class="summary-icon summary-icon--amber"><v-icon size="19">mdi-road-variant</v-icon></div><div><div class="summary-value">{{ totalDistance }}</div><div class="summary-label">Kilómetros configurados</div></div></div></v-col>
      </v-row>

      <v-card class="table-panel" elevation="0">
        <div class="table-toolbar"><div><div class="section-title">Listado de rutas</div><div class="section-subtitle">{{ registeredCountText }}</div></div><v-text-field v-model="search" class="search-field" density="compact" placeholder="Buscar ruta..." prepend-inner-icon="mdi-magnify" variant="outlined" hide-details clearable /></div>
        <v-divider />

        <v-data-table v-model:items-per-page="itemsPerPage" v-model:page="page" v-model:sort-by="sortBy" :headers="headers" :items="branchRoutes" :search="search" :loading="loading" :items-per-page-options="[5,10,15,25]" items-per-page-text="Elementos por página" no-data-text="No hay rutas disponibles" loading-text="Cargando rutas..." class="routes-table">
          <template #loading><v-skeleton-loader type="table-row@5" /></template>
          <template #[`item.code`]="{ item }"><div class="route-code-cell"><div class="route-icon"><v-icon size="18">mdi-road-variant</v-icon></div><div><div class="route-code">{{ item.code || "Sin código" }}</div></div></div></template>
          <template #[`item.originAddress`]="{ item }"><div class="location-cell"><div class="location-avatar"><v-img v-if="item.originImage" :src="imageUrl(item.originImage)" class="location-photo" width="36" height="36" cover><template #error><div class="location-fallback"><v-icon size="17">mdi-map-marker-outline</v-icon></div></template></v-img><v-icon v-else size="17">mdi-map-marker-outline</v-icon></div><span :title="item.originAddress">{{ item.originAddress || "Sin origen" }}</span></div></template>
          <template #[`item.destinationAddress`]="{ item }"><div class="location-cell"><div class="location-avatar"><v-img v-if="item.destinationImage" :src="imageUrl(item.destinationImage)" class="location-photo" width="36" height="36" cover><template #error><div class="location-fallback"><v-icon size="17">mdi-map-marker-outline</v-icon></div></template></v-img><v-icon v-else size="17">mdi-map-marker-outline</v-icon></div><span :title="item.destinationAddress">{{ item.destinationAddress || "Sin destino" }}</span></div></template>
          <template #[`item.distance`]="{ item }"><span class="metric-badge"><v-icon size="14">mdi-ruler</v-icon>{{ formatMetric(item.distance) }} km</span></template>
          <template #[`item.estimated`]="{ item }"><span class="time-value"><v-icon size="14">mdi-timer-outline</v-icon>{{ formatMetric(item.estimated) }} min</span></template>
          <template #[`item.actions`]="{ item }"><div class="action-buttons">
            <v-tooltip text="Gestionar paradas" location="top"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-map-marker-path" variant="text" size="small" class="action-button action-button--stops" @click="openRouteStops(item)" /></template></v-tooltip>
            <v-tooltip text="Gestionar tramos" location="top"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-cash-multiple" variant="text" size="small" class="action-button action-button--segments" @click="openFareSegments(item)" /></template></v-tooltip>
            <v-tooltip text="Editar ruta" location="top"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-pencil-outline" variant="text" size="small" class="action-button action-button--edit" @click="editItem(item)" /></template></v-tooltip>
            <v-tooltip text="Eliminar ruta" location="top"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-trash-can-outline" variant="text" size="small" class="action-button action-button--delete" @click="deleteItem(item)" /></template></v-tooltip>
          </div></template>
        </v-data-table>
        <div class="table-footer-note"><v-icon size="15">mdi-information-outline</v-icon>Gestiona las paradas y tramos comerciales desde las acciones de cada ruta.</div>
      </v-card>
    </v-container>

    <v-dialog v-model="dialog" max-width="680" persistent>
      <v-form ref="form" v-model="valid" @submit.prevent="save"><v-card class="form-dialog" elevation="0">
        <div class="dialog-header"><div class="dialog-heading"><div class="dialog-icon"><v-icon class="dialog-icon-main" size="20">mdi-routes</v-icon><v-icon class="dialog-icon-action" size="11">{{ editedIndex === -1 ? "mdi-plus" : "mdi-pencil" }}</v-icon></div><div><div class="dialog-title">{{ formTitle }}</div><div class="dialog-subtitle">{{ editedIndex === -1 ? "Configura un nuevo recorrido operativo" : "Actualiza la información de la ruta" }}</div></div></div><v-btn icon="mdi-close" variant="text" size="small" class="dialog-close" :disabled="loading" @click="close" /></div>
        <v-divider />
        <v-card-text class="dialog-body">
          <div class="form-section-label">Identificación de la ruta</div>
          <v-text-field v-model.trim="editedItem.code" label="Código de la ruta" placeholder="Ej.: AER-TPM" prepend-inner-icon="mdi-pound" variant="outlined" density="comfortable" :rules="codeRules" maxlength="20" counter="20" @blur="normalizeRouteCodeInput" />
          <div class="form-section-label form-section-label--spaced">Recorrido</div>
          <v-row dense>
            <v-col cols="12" md="6">
              <v-autocomplete v-model="editedItem.origin_id" :items="locationsOrigins" item-title="address" item-value="id" label="Origen" prepend-inner-icon="mdi-map-marker-up-outline" variant="outlined" density="comfortable" no-data-text="No hay orígenes disponibles" :rules="selectRules" class="route-location-select">
                <template #item="{ props, item }"><v-list-item v-bind="props" class="location-option"><template #prepend><v-avatar size="34" rounded="lg" class="option-avatar"><v-img v-if="item.raw.image" :src="imageUrl(item.raw.image)" width="34" height="34" cover><template #error><div class="option-fallback"><v-icon size="17">mdi-map-marker-outline</v-icon></div></template></v-img><v-icon v-else size="17">mdi-map-marker-outline</v-icon></v-avatar></template><v-list-item-title class="option-title">{{ item.raw.city }}</v-list-item-title></v-list-item></template>
              </v-autocomplete>
            </v-col>
            <v-col cols="12" md="6">
              <v-autocomplete v-model="editedItem.destination_id" :items="availableDestinations" item-title="address" item-value="id" label="Destino" prepend-inner-icon="mdi-map-marker-down-outline" variant="outlined" density="comfortable" no-data-text="No hay destinos disponibles" :rules="selectRules" class="route-location-select">
                <template #item="{ props, item }"><v-list-item v-bind="props" class="location-option"><template #prepend><v-avatar size="34" rounded="lg" class="option-avatar"><v-img v-if="item.raw.image" :src="imageUrl(item.raw.image)" width="34" height="34" cover><template #error><div class="option-fallback"><v-icon size="17">mdi-map-marker-outline</v-icon></div></template></v-img><v-icon v-else size="17">mdi-map-marker-outline</v-icon></v-avatar></template><v-list-item-title class="option-title">{{ item.raw.city }}</v-list-item-title></v-list-item></template>
              </v-autocomplete>
            </v-col>
            <v-col cols="12" md="6"><v-text-field v-model="editedItem.distance" label="Distancia" suffix="km" prepend-inner-icon="mdi-ruler" variant="outlined" density="comfortable" type="number" min="0" step="0.01" :rules="distanceRules" /></v-col>
            <v-col cols="12" md="6"><v-text-field v-model="editedItem.estimated" label="Duración estimada" suffix="min" prepend-inner-icon="mdi-timer-outline" variant="outlined" density="comfortable" type="number" min="1" :rules="durationRules" /></v-col>
          </v-row>
          <div class="route-preview"><div class="preview-point preview-point--origin"><v-icon size="16">mdi-map-marker</v-icon></div><div class="preview-line" /><div class="preview-point preview-point--destination"><v-icon size="16">mdi-flag-checkered</v-icon></div><div class="preview-copy"><span>{{ selectedOriginName }}</span><v-icon size="15">mdi-arrow-right</v-icon><span>{{ selectedDestinationName }}</span></div></div>
        </v-card-text>
        <v-divider /><v-card-actions class="dialog-actions"><v-btn variant="text" class="cancel-button" :disabled="loading" @click="close">Cancelar</v-btn><v-btn type="submit" class="save-button" elevation="0" :loading="loading" :disabled="!valid">{{ editedIndex === -1 ? "Crear ruta" : "Guardar cambios" }}</v-btn></v-card-actions>
      </v-card></v-form>
    </v-dialog>

    <v-dialog v-model="dialogDelete" max-width="430" persistent><v-card class="delete-dialog" elevation="0"><div class="delete-icon"><v-icon size="27">mdi-trash-can-outline</v-icon></div><div class="delete-title">Eliminar ruta</div><div class="delete-message">¿Deseas eliminar la ruta <strong>{{ editedItem.code || "seleccionada" }}</strong>? Esta acción no se puede deshacer.</div><div class="delete-actions"><v-btn variant="text" class="cancel-button" :disabled="loading" @click="closeDelete">Cancelar</v-btn><v-btn class="delete-button" elevation="0" :loading="loading" @click="deleteItemConfirm">Eliminar</v-btn></div></v-card></v-dialog>

    <v-dialog v-model="dialogRouteStop" fullscreen transition="dialog-bottom-transition"><v-card class="sublevel-dialog"><RouteStop :route="selectedRoute" @close="closeDialogRouteStop" /></v-card></v-dialog>
    <v-dialog v-model="dialogFareSegment" fullscreen transition="dialog-bottom-transition"><v-card class="sublevel-dialog"><FareSegment :route="selectedRoute" @close="closeDialogFareSegment" /></v-card></v-dialog>
  </div>
</template>

<script>
import { handleRequest } from "@/utils/api";
import LocalStorageService from "@/LocalStorageService";
import RouteStop from "./RouteStop.vue";
import FareSegment from "./FareSegment.vue";

export default {
  name: "RoutesView",
  components: { RouteStop, FareSegment },
  data: () => ({
    snackbar:false,sb_type:"",sb_message:"",sb_timeout:2000,sb_title:"",sb_icon:"",valid:false,loading:false,dialog:false,dialogDelete:false,
    locations:[],locationsOrigins:[],filteredDestinations:[],branchRoutes:[],branch_id:"",permissions:"",selectedRoute:{},dialogRouteStop:false,dialogFareSegment:false,
    search:"",page:1,itemsPerPage:10,sortBy:[],editedIndex:-1,
    headers:[
      {title:"Código",key:"code",sortable:true,width:"14%"},{title:"Origen",key:"originAddress",sortable:true,width:"24%"},{title:"Destino",key:"destinationAddress",sortable:true,width:"24%"},{title:"Distancia",key:"distance",sortable:true,width:"11%"},{title:"Duración",key:"estimated",sortable:true,width:"11%"},{title:"",key:"actions",sortable:false,align:"end",width:"16%"},
    ],
    editedItem:{id:"",code:"",origin_id:"",destination_id:"",distance:"",estimated:"",status:"1",route_id:"",branch_id:""},
    defaultItem:{id:"",code:"",origin_id:"",destination_id:"",distance:"",estimated:"",status:"1",route_id:"",branch_id:""},originalItem:{},
    codeRules:[v=>!!String(v||"").trim()||"El código es requerido",v=>!v||String(v).length<=20||"Máximo 20 caracteres"],
    selectRules:[v=>!!v||"Debes seleccionar una ubicación"],distanceRules:[v=>v!==""&&!isNaN(v)||"Ingresa una distancia válida",v=>Number(v)>0||"Debe ser mayor a 0"],durationRules:[v=>v!==""&&!isNaN(v)||"Ingresa una duración válida",v=>Number(v)>0||"Debe ser mayor a 0"],
  }),
  computed:{
    formTitle(){return this.editedIndex===-1?"Agregar ruta":"Editar ruta";},
    availableDestinations(){return this.locations.filter(x=>String(x.id)!==String(this.editedItem.origin_id));},
    activeRoutes(){return this.branchRoutes.filter(x=>Number(x.status??1)===1).length;},
    uniqueLocations(){const ids=new Set();this.branchRoutes.forEach(x=>{if(x.origin_id)ids.add(String(x.origin_id));if(x.destination_id)ids.add(String(x.destination_id));});return ids.size;},
    totalDistance(){return this.branchRoutes.reduce((sum,x)=>sum+(Number(x.distance)||0),0).toLocaleString("es-CL",{maximumFractionDigits:1});},
    registeredCountText(){return this.branchRoutes.length===1?"1 ruta registrada":`${this.branchRoutes.length} rutas registradas`;},
    selectedOriginName(){return this.locationsOrigins.find(x=>String(x.id)===String(this.editedItem.origin_id))?.address||"Selecciona origen";},
    selectedDestinationName(){return this.locations.find(x=>String(x.id)===String(this.editedItem.destination_id))?.address||"Selecciona destino";},
  },
  watch:{search(){this.page=1;},"editedItem.origin_id"(value){if(String(value)===String(this.editedItem.destination_id))this.editedItem.destination_id="";}},
  mounted(){this.branch_id=this.normalizeStorage(LocalStorageService.getItem("branch_id"));this.permissions=LocalStorageService.getItem("permissions")||"";this.initialize();},
  methods:{
    normalizeStorage(v){return String(v??"").replace(/["']/g,"").trim();},unwrapItem(item){return item?.raw??item??{};},cloneItem(item){return{...item};},
    normalizeRouteRecord(route={}){return{...route,id:route.id??route.route_id??"",route_id:route.route_id??route.id??"",code:route.code??route.routeCode??"",origin_id:route.origin_id??route.originId??"",destination_id:route.destination_id??route.destinationId??"",originAddress:route.originAddress??route.originName??"",destinationAddress:route.destinationAddress??route.destinationName??"",originImage:route.originImage??"",destinationImage:route.destinationImage??""};},
    normalizeRouteCodeValue(v=""){return String(v).trim().toUpperCase();},normalizeRouteCodeInput(){this.editedItem.code=this.normalizeRouteCodeValue(this.editedItem.code);},
    isUniqueRouteCode(v){const code=this.normalizeRouteCodeValue(v);return!this.branchRoutes.some(x=>this.normalizeRouteCodeValue(x.code)===code&&String(x.id??x.route_id)!==String(this.editedItem.id));},
    imageUrl(source){if(!source)return"";const image=String(source).trim();if(/^(https?:|data:|blob:)/i.test(image))return image;const base=String(this.$axios.defaults.baseURL||"");const clean=image.replace(/^\/+/,"");return clean.startsWith("images/")?`${base}${clean}`:`${base}images/${clean}`;},
    formatMetric(v){const n=Number(v);return Number.isFinite(n)?n.toLocaleString("es-CL",{maximumFractionDigits:2}):"0";},
    resetEditor(){this.editedItem=this.cloneItem(this.defaultItem);this.originalItem=this.cloneItem(this.defaultItem);this.editedIndex=-1;this.valid=false;},
    async loadLocations(){const result=await handleRequest({endpoint:"location-route",method:"POST",data:{}});this.locations=result.success?(result.data?.destinations||[]):[];this.locationsOrigins=result.success?(result.data?.origins||[]):[];this.filteredDestinations=this.locations;},
    async showAdd(){this.resetEditor();try{await this.loadLocations();}catch(e){this.showAlert("error","No fue posible cargar las ubicaciones.",3000);}finally{this.dialog=true;this.$nextTick(()=>this.$refs.form?.resetValidation());}},
    close(){if(this.loading)return;this.dialog=false;this.$nextTick(()=>{this.resetEditor();this.$refs.form?.resetValidation();});},
    async initialize(){this.loading=true;try{const result=await handleRequest({endpoint:"route",method:"GET",data:{}});this.branchRoutes=result.success?(result.data?.routes||[]).map(x=>this.normalizeRouteRecord(x)):[];if(!result.success)this.showAlert("warning",result.message||"No fue posible cargar las rutas.",3000);}catch(e){this.branchRoutes=[];this.showAlert("error","Ocurrió un error al cargar las rutas.",3000);}finally{this.loading=false;}},
    async save(){const validation=await this.$refs.form?.validate();if(!validation?.valid)return;this.editedItem.code=this.normalizeRouteCodeValue(this.editedItem.code);if(!this.isUniqueRouteCode(this.editedItem.code)){this.showAlert("warning","Ya existe una ruta con ese código en esta empresa.",3000);return;}const creating=this.editedIndex===-1;const fields=["code","origin_id","destination_id","distance","estimated","status","route_id"];const payload=fields.reduce((o,k)=>{if(creating||this.editedItem[k]!==this.originalItem[k])o[k]=this.editedItem[k];return o;},{});if(!creating&&!Object.keys(payload).length){this.showAlert("warning","No se realizaron cambios.",3000);return;}if(!creating)payload.id=this.editedItem.id;this.loading=true;try{const result=await handleRequest({endpoint:"route",method:creating?"POST":"PUT",data:payload});if(result.success){this.dialog=false;this.showAlert("success",result.message||"Ruta guardada correctamente.",3000);await this.initialize();this.resetEditor();}else this.showAlert("warning",result.message||"No fue posible guardar la ruta.",3000);}catch(e){this.showAlert("error","Ocurrió un error al guardar la ruta.",3000);}finally{this.loading=false;}},
    async editItem(item){const route=this.normalizeRouteRecord(this.unwrapItem(item));this.editedIndex=this.branchRoutes.findIndex(x=>String(x.id)===String(route.id));this.originalItem=this.cloneItem(route);this.editedItem=this.cloneItem(route);try{await this.loadLocations();}catch(e){this.showAlert("error","No fue posible cargar las ubicaciones.",3000);}finally{this.dialog=true;this.$nextTick(()=>this.$refs.form?.resetValidation());}},
    deleteItem(item){const route=this.unwrapItem(item);this.editedItem={...this.defaultItem,...route};this.dialogDelete=true;},closeDelete(){if(!this.loading){this.dialogDelete=false;this.resetEditor();}},
    async deleteItemConfirm(){this.loading=true;try{const result=await handleRequest({endpoint:"route-destroy",method:"POST",data:{id:this.editedItem.id}});if(result.success){this.dialogDelete=false;this.showAlert("success",result.message||"Ruta eliminada correctamente.",3000);await this.initialize();this.resetEditor();}else this.showAlert("warning",result.message||"No fue posible eliminar la ruta.",3000);}catch(e){this.showAlert("error","Ocurrió un error al eliminar la ruta.",3000);}finally{this.loading=false;}},
    openRouteStops(item){const x=this.unwrapItem(item);this.selectedRoute={...x,id:x.route_id??x.id,route_id:x.route_id??x.id,name:x.code||x.name};this.dialogRouteStop=true;},openFareSegments(item){const x=this.unwrapItem(item);this.selectedRoute={...x,id:x.route_id??x.id,route_id:x.route_id??x.id,name:x.code||x.name};this.dialogFareSegment=true;},closeDialogRouteStop(){this.dialogRouteStop=false;this.selectedRoute={};},closeDialogFareSegment(){this.dialogFareSegment=false;this.selectedRoute={};},
    showAlert(type,message,timeout=3000){const cfg={success:["Éxito","mdi-check-circle"],error:["Error","mdi-close-circle"],warning:["Advertencia","mdi-alert-circle"],info:["Información","mdi-information"]}[type]||["Advertencia","mdi-alert-circle"];this.sb_type=type;this.sb_title=cfg[0];this.sb_icon=cfg[1];this.sb_message=message;this.sb_timeout=timeout;this.snackbar=true;},
  },
};
</script>

